      sources: sources.map((s) => ({
        id: s.id,
        title: s.title,
        url: s.url,
        domain: s.domain,
        branch: s.branch,
        role: s.role,
        engines_matched: s.engines_matched || [s.search_engine],
        is_hydrated: s.is_hydrated,
        hydrated_type: s.hydrated_type,
        is_native_pdf: Boolean(s.is_native_pdf),
        publishedDate: s.publishedDate || null,
        retrievedAt: s.retrievedAt || today,
        credibility_label: s.credibility_label,
        cites: s.cites || [],
        cited_by: s.cited_by || [],
        disclosure_note: s.disclosure_note || null,
        sift_audit: s.sift_audit
      })),
